import os,json,re
def parse(t):
    m=re.search(r'Demo pair 1 input \((\d+)x(\d+)\):\n',t); h,w=int(m[1]),int(m[2])
    rows=[list(map(int,r.split())) for r in t[m.end():].split('\n')[:h]]
    m2=re.search(r'Demo pair 1 output \((\d+)x(\d+)\):\n',t); h2,w2=int(m2[1]),int(m2[2])
    out=[list(map(int,r.split())) for r in t[m2.end():].split('\n')[:h2]]
    return rows,out
t=open(os.environ['RLM_SESSION_DIR']+'/../../sessions/'+os.path.basename(os.environ['RLM_SESSION_DIR'])+'.jsonl').read()
inp,out=parse(t)

def find_objects(g):
    bg=g[0][0]
    seen=set(); objs=[]
    for i,row in enumerate(g):
        for j,v in enumerate(row):
            if v!=bg and (i,j) not in seen:
                stack=[(i,j)]; comp=set()
                while stack:
                    y,x=stack.pop()
                    if (y,x) in comp or g[y][x]==bg: continue
                    comp.add((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<len(g) and 0<=nx<len(g[0]): stack.append((ny,nx))
                objs.append(comp); seen|=comp
    return bg,objs

bg,objs=find_objects(inp)
for o in objs: print(bg,len(o),sorted(o)[:6])

def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
